import type { CitationEvidence } from "../rag/types";
import type { SafetyEvaluation } from "./types";
import {
  validateCitations,
  type CitationValidationResult,
} from "./citationValidation";
import { DEFINITIVE_DIAGNOSIS_PATTERNS } from "./validators/diagnosticLanguage";

/**
 * Final delivery gate for model output.
 *
 * Nothing generated by the model is sent to a client unless it passes this
 * gate. The gate is deliberately conservative: if validation is missing,
 * incomplete, or ambiguous, the caller receives a static safe fallback.
 */

export const SAFE_FALLBACK_MESSAGE =
  "I'm unable to provide a validated response right now. Please consult a qualified healthcare professional for medical advice.";

/**
 * Individualized instructions such as "take 400 mg" or "increase your dose"
 * are not appropriate for an educational assistant, even when a generic
 * disclaimer is present.
 */
const INDIVIDUALIZED_MEDICATION_PATTERNS: RegExp[] = [
  /\b(take|use|give|administer)\s+\d+(\.\d+)?\s*(mg|mcg|g|ml|tablet|capsule|puff|drop)s?\b/i,
  /\byour\s+(dose|dosage)\b/i,
  /\b(increase|decrease|double|stop|skip)\s+(your\s+)?(dose|dosage|medication)\b/i,
];

export interface ResponseGateInput {
  generatedText: string;
  citations: CitationEvidence[];
  safety: SafetyEvaluation | null;
  safetyError?: string;
}

export interface ResponseGateResult {
  safe: boolean;
  responseText: string;
  reason: string;
  citationValidation: CitationValidationResult;
}

function fallbackFor(safety: SafetyEvaluation | null): string {
  if (safety?.action === "block" && safety.fallbackMessage) {
    return safety.fallbackMessage;
  }
  return SAFE_FALLBACK_MESSAGE;
}

export function applyResponseGate(input: ResponseGateInput): ResponseGateResult {
  const citationValidation = validateCitations(input.generatedText, input.citations);

  if (!citationValidation.valid) {
    return {
      safe: false,
      responseText: fallbackFor(input.safety),
      reason: "citation_validation_failed",
      citationValidation,
    };
  }

  if (input.safetyError) {
    return {
      safe: false,
      responseText: SAFE_FALLBACK_MESSAGE,
      reason: "safety_check_failed",
      citationValidation,
    };
  }

  if (!input.safety) {
    return {
      safe: false,
      responseText: SAFE_FALLBACK_MESSAGE,
      reason: "safety_check_missing",
      citationValidation,
    };
  }

  // A validator crash is reported as overallStatus "failed" with an "allow"
  // action by the framework. That is an incomplete evaluation, not a pass.
  if (
    input.safety.action !== "allow" ||
    input.safety.overallStatus === "failed" ||
    input.safety.overallStatus === "blocked"
  ) {
    return {
      safe: false,
      responseText: fallbackFor(input.safety),
      reason:
        input.safety.action !== "allow"
          ? `safety_${input.safety.action}`
          : "safety_incomplete",
      citationValidation,
    };
  }

  if (DEFINITIVE_DIAGNOSIS_PATTERNS.some((pattern) => pattern.test(input.generatedText))) {
    return {
      safe: false,
      responseText: SAFE_FALLBACK_MESSAGE,
      reason: "unsupported_diagnosis",
      citationValidation,
    };
  }

  if (INDIVIDUALIZED_MEDICATION_PATTERNS.some((pattern) => pattern.test(input.generatedText))) {
    return {
      safe: false,
      responseText: SAFE_FALLBACK_MESSAGE,
      reason: "individualized_medication_advice",
      citationValidation,
    };
  }

  return {
    safe: true,
    responseText: input.generatedText,
    reason: "validated",
    citationValidation,
  };
}
